/*
 * Replay the trace generated by `lake exe mpmc-kernel-trace` through the
 * generated C kernel and check every result against a simple FIFO model.
 * This is the differential test between the Lean interpreter and the C
 * code generator: both consume the same `tests/kernel_trace.txt`.
 *
 * The trace test needs the raw kernel status and sequence numbers, which
 * the public API hides, so it uses the internal detail header
 * and the generated kernel directly.
 */
#include "mpmc.h"

#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int failures = 0;

#define CHECK(cond)                                                          \
  do {                                                                       \
    if (!(cond)) {                                                           \
      fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);        \
      ++failures;                                                            \
    }                                                                        \
  } while (0)

int main(int argc, char **argv) {
  const char *path = argc > 1 ? argv[1] : "tests/kernel_trace.txt";
  FILE *file = fopen(path, "r");
  if (file == NULL) {
    fprintf(stderr, "trace: cannot open %s\n", path);
    return 1;
  }

  unsigned long capacity = 0;
  unsigned long limit = 0;
  char line[256];
  if (fgets(line, sizeof(line), file) == NULL ||
      sscanf(line, "capacity %lu", &capacity) != 1) {
    fprintf(stderr, "trace: missing capacity\n");
    fclose(file);
    return 1;
  }
  if (fgets(line, sizeof(line), file) == NULL ||
      sscanf(line, "limit %lu", &limit) != 1) {
    fprintf(stderr, "trace: missing limit\n");
    fclose(file);
    return 1;
  }

  mpmc_queue *q = mpmc_new((uint64_t)capacity, (uint64_t)limit);
  CHECK(q != NULL);
  if (q == NULL) {
    fclose(file);
    return 1;
  }

  uint64_t *values = (uint64_t *)calloc(limit + 1, sizeof(uint64_t));
  if (values == NULL) {
    fprintf(stderr, "trace: allocation failed\n");
    fclose(file);
    mpmc_destroy(q);
    return 1;
  }

  uint64_t W = 0;
  uint64_t R = 0;
  uint64_t operations = 0;

  while (fgets(line, sizeof(line), file) != NULL) {
    line[strcspn(line, "\r\n")] = '\0';
    if (line[0] == '\0') {
      continue;
    }
    ++operations;

    if (strncmp(line, "push ", 5) == 0) {
      const uint64_t value = strtoull(line + 5, NULL, 10);
      mpmc_kernel_status expected;
      uint64_t expected_seq = 0;
      if (W >= limit) {
        expected = MPMC_KERNEL_EXHAUSTED;
      } else if (W - R >= capacity) {
        expected = MPMC_KERNEL_FULL;
      } else {
        expected = MPMC_KERNEL_OK;
        expected_seq = W;
      }

      uint64_t seq = 0;
      const mpmc_kernel_status status = (mpmc_kernel_status)mpmc_kernel_push(
          q, q->capacity, q->mask, q->limit, value, &seq);
      CHECK(status == expected);
      if (status == MPMC_KERNEL_OK) {
        CHECK(seq == expected_seq);
        values[W] = value;
        ++W;
      }
    } else if (strcmp(line, "pop") == 0) {
      mpmc_kernel_status expected;
      uint64_t expected_seq = 0;
      uint64_t expected_value = 0;
      if (R >= limit) {
        expected = MPMC_KERNEL_EXHAUSTED;
      } else if (R == W) {
        expected = MPMC_KERNEL_EMPTY;
      } else {
        expected = MPMC_KERNEL_OK;
        expected_seq = R;
        expected_value = values[R];
      }

      uint64_t value = 0;
      uint64_t seq = 0;
      const mpmc_kernel_status status = (mpmc_kernel_status)mpmc_kernel_pop(
          q, q->capacity, q->mask, q->limit, &value, &seq);
      CHECK(status == expected);
      if (status == MPMC_KERNEL_OK) {
        CHECK(seq == expected_seq);
        CHECK(value == expected_value);
        ++R;
      }
    } else {
      fprintf(stderr, "trace: bad line '%s'\n", line);
      ++failures;
    }
    CHECK(mpmc_size_approx_internal(q) == W - R);
  }

  fclose(file);
  free(values);
  mpmc_destroy(q);

  if (failures != 0) {
    fprintf(stderr, "kernel trace: %d failure(s) over %" PRIu64
                    " operations\n", failures, operations);
    return 1;
  }
  printf("kernel trace: ok (%" PRIu64 " operations)\n", operations);
  return 0;
}
